const cmds = [
  "sed -n '1,280p' docs/product-specs/vercel-production-promotion.md",
  "jq '.tasks[] | select(.id == \"deploy-and-prove-production-agent\")' docs/product-specs/vercel-production-promotion.tasks.json",
  "sed -n '1,340p' docs/exec-plans/active/vercel-production-promotion.md",
  "sed -n '1,280p' docs/architecture/effect-patterns.md",
  "sed -n '1,300p' docs/architecture/eve-agent.md",
  "sed -n '1,300p' docs/architecture/testing-and-quality.md",
  "sed -n '1,260p' apps/agent/README.md",
  "cat package.json && printf '\\n--- agent ---\\n' && cat apps/agent/package.json && printf '\\n--- proxy ---\\n' && cat apps/codex-proxy/package.json"
];
const results = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/Users/cooper/Projects/bundjil",yield_time_ms:10000,max_output_tokens:20000})));
text(results.map((r,i)=>`### ${i+1}\n${r.output}`).join("\n"));

const cmds = [
"rg -n \"proxy-accepted-agent-configured|production-preflight|snapshot|vercel\" apps/agent/scripts apps/agent/test apps/agent/agent docs/exec-plans/active/vercel-production-promotion.md docs/product-specs/vercel-production-promotion.md | head -260",
"rg -n -A100 -B20 \"deploy-and-prove-production-agent|deploy-and-accept-production-proxy|proxy-accepted-agent-configured\" docs/exec-plans/active/vercel-production-promotion.md",
"find apps/agent -maxdepth 3 -type f | sort",
"rg -n \"BUNDJIL_AGENT_MODEL_PROVIDER|BUNDJIL_CODEX_PROXY\" turbo.json apps/agent vercel.json apps/agent/vercel.json 2>/dev/null",
"git log -1 --format='%H %D' && git status --porcelain=v1 && git remote -v"
];
const results = await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/Users/cooper/Projects/bundjil",yield_time_ms:10000,max_output_tokens:30000})));
text(results.map((r,i)=>`### ${i+1}\n${r.output}`).join("\n"));

const cmds = [
"sed -n '215,410p' docs/exec-plans/active/vercel-production-promotion.md",
"sed -n '1,390p' apps/agent/agent/production-preflight.ts",
"sed -n '1,120p' apps/agent/scripts/production-preflight.ts && sed -n '1,220p' apps/agent/test/production-preflight.test.ts",
"command -v vercel; vercel --version; command -v op; op --version; command -v jq; command -v gh",
"find .local -maxdepth 3 -type f 2>/dev/null | sort | head -100",
"rg -n \"vercel deploy|oidc|session.waiting|startIndex|bypass|logs\" docs apps .agents --glob '!**/.workflow-data/**' | head -300"
];
const results = await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/Users/cooper/Projects/bundjil",yield_time_ms:10000,max_output_tokens:40000})));
text(results.map((r,i)=>`### ${i+1}\n${r.output}`).join("\n"));

const cmds = [
"vercel project inspect bundjil-agent --scope REDACTED --json 2>&1 | jq '{id,name,accountId,link,targets,protectionBypass, ssoProtection}'",
"vercel env ls --project bundjil-agent --scope REDACTED 2>&1",
"vercel ls --project bundjil-agent --scope REDACTED --meta gitHash=9a34a34e5ebc320fb30cd96c8651585d2fc0e770 2>&1 | head -80",
"vercel env add --help | sed -n '1,220p'",
"op account list 2>&1 && op vault get personal-vault --format json 2>&1 | jq '{id,name}'"
];
const results=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/Users/cooper/Projects/bundjil",yield_time_ms:30000,max_output_tokens:20000})));
text(results.map((r,i)=>`### ${i+1}\n${r.output}`).join("\n"));

