const cmds = [
"git status --short && git rev-parse HEAD && git rev-parse origin/main",
"sed -n '490,565p' docs/architecture/eve-agent.md",
"sed -n '260,390p' apps/agent/README.md",
"find . -path '*/.vercel/project.json' -type f -maxdepth 4 -print -exec sed -n '1,80p' {} \\;",
"bunx vercel --version",
"bunx vercel env ls --project bundjil-agent --scope REDACTED 2>&1",
"bunx vercel project inspect bundjil-agent --scope REDACTED --json 2>&1 | head -c 30000"
];
const results=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/Users/cooper/Projects/bundjil",yield_time_ms:30000,max_output_tokens:30000})));
text(results.map((r,i)=>`### ${i+1}\n${r.output}`).join("\n"));

